const tiers=[{name:'Rookie Cup',laps:3,req:0,reward:40,trophies:12},{name:'Street League',laps:4,req:1,reward:140,trophies:32},{name:'Pro Grand Prix',laps:5,req:2,reward:480,trophies:85},{name:'Elite Tour',laps:6,req:3,reward:1600,trophies:220},{name:'World Apex Championship',laps:8,req:4,reward:6000,trophies:650}];
const cars=[['Comet S','Compact Coupe','🚙','Common'],['V8 Raptor','Muscle GT','🏎️','Rare'],['Crown Interceptor','Police Interceptor','🚓','Rare'],['Trail Boss','Pickup Truck','🛻','Common'],['Sidewinder','Drift Van','🚐','Epic'],['Pocket Rocket','RC Buggy','🏁','Common'],['Dune Raider','Off-Roader','🚜','Rare'],['Aurelia GT','Mid-Engine Supercar','🏎️','Epic'],['Apex F1','Formula Racer','🏎️','Legendary'],['Retro Nova','Classic Coupe','🚗','Common'],['Nightshift','Street Racer','🚘','Rare'],['Volt Runner','Electric Hypercar','⚡','Epic'],['Rally Fox','Rally Hatchback','🚗','Rare'],['Roadster 88','Open Roadster','🚘','Rare'],['Titan Hauler','Heavy Truck','🚚','Epic'],['Skyline X','Hypercar','🏎️','Legendary'],['Rookie Kart','Track Kart','🏎️','Common'],['Phantom GT','Luxury Coupe','🚘','Epic']];
const packDefs=[{name:'Standard Pack',icon:'📦',colors:['#55d8ac','#176e6e'],cost:140,trophies:0,weights:[65,25,9,1]},{name:'Pro Pack',icon:'🎴',colors:['#55b8ff','#3648ab'],cost:850,trophies:0,weights:[35,40,21,4]},{name:'Neon Pack',icon:'💠',colors:['#e860ff','#693fd7'],cost:2400,trophies:22,weights:[15,35,38,12]},{name:'Legendary Pack',icon:'👑',colors:['#ffce67','#dc6545'],cost:0,trophies:90,weights:[4,16,42,38]}];
const statDefs=[['speed','Top Speed','Higher cruising speed'],['accel','Acceleration','Faster lap pace'],['grip','Cornering Grip','More drift efficiency'],['nitro','Nitro Boost','Bigger burst bonus'],['payout','Race Payout','More cash per lap']];
const fresh=()=>({cash:650,trophies:0,xp:0,level:1,laps:0,world:0,car:0,upgrades:{speed:0,accel:0,grip:0,nitro:0,payout:0},collection:{0:1},skins:0,prestige:0,unlockedTier:0,won:[],worlds:[0],speedMult:1,follow:true,sound:true,last:Date.now(),champ:null});
let state;try{state={...fresh(),...JSON.parse(localStorage.getItem('pitlane-save')||'{}')};state.upgrades={...fresh().upgrades,...state.upgrades};state.collection=state.collection||{0:1};state.worlds=state.worlds||[0];}catch{state=fresh()}
let tab='race',buyMode=1,ctx=null,toastTimer,champTimer=0,sceneTime=0,lastTick=Date.now();
const $=s=>document.querySelector(s),fmt=n=>Math.floor(n).toLocaleString(),save=()=>{state.last=Date.now();localStorage.setItem('pitlane-save',JSON.stringify(state))};
function notify(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2300)}
function sound(type='tap'){if(!state.sound)return;try{ctx=ctx||new(window.AudioContext||window.webkitAudioContext)();const osc=ctx.createOscillator(),gain=ctx.createGain();osc.connect(gain);gain.connect(ctx.destination);const now=ctx.currentTime,notes={tap:[440,.05],upgrade:[660,.13],pack:[520,.23],lap:[740,.1],win:[880,.4]};osc.frequency.setValueAtTime(notes[type][0],now);osc.frequency.exponentialRampToValueAtTime(notes[type][0]*1.45,now+notes[type][1]);osc.type=type==='win'?'triangle':'sine';gain.gain.setValueAtTime(.055,now);gain.gain.exponentialRampToValueAtTime(.001,now+notes[type][1]);osc.start(now);osc.stop(now+notes[type][1])}catch{}}
const rate=()=> (1+state.upgrades.payout*.16)*(1+state.prestige*.18)*(1+state.car*.018)*(1+Math.max(0,state.skins)*.02);
const lapSeconds=()=>Math.max(8,30-state.upgrades.speed*1.1-state.upgrades.accel*.9-state.upgrades.grip*.45-state.upgrades.nitro*.3);
function addXp(n){state.xp+=n;while(state.xp>=state.level*100){state.xp-=state.level*100;state.level++;state.cash+=120;notify('Level up! +$120 bonus')}}
// Catch up a maximum of 12 hours from the saved timestamp.
{const away=Math.min(12*3600,Math.max(0,(Date.now()-(state.last||Date.now()))/1000));if(away>8){const earned=away/lapSeconds()*16*rate();state.cash+=earned;state.laps+=Math.floor(away/lapSeconds());addXp(Math.floor(away*0.18));setTimeout(()=>notify(`Welcome back! Your crew earned $${fmt(earned)} while you were away.`),350)}}

