function handleClick(e){const b=e.target.closest('button');if(!b)return;const a=b.dataset;
if(a.tab){tab=a.tab;render();return}if(a.speed){state.speedMult=+a.speed;save();sound();render();return}if(a.buy){buyMode=+a.buy;render();return}if(a.camera!==undefined){state.follow=!state.follow;save();sound();render();return}if(a.sound!==undefined){state.sound=!state.sound;save();sound('tap');render();return}
if(a.upgrade){const cost=upgradeCost(a.upgrade,buyMode);if(state.cash<cost)return notify('Not enough cash for that upgrade.');state.cash-=cost;state.upgrades[a.upgrade]+=buyMode;addXp(buyMode*8);sound('upgrade');notify(`${a.upgrade[0].toUpperCase()+a.upgrade.slice(1)} upgraded to level ${state.upgrades[a.upgrade]}`);save();render();return}
